const rawText = $('Claude API').item.json.content[0].text;
const today = new Date().toLocaleDateString('en-NZ');

// Markdownをプロフェッショナルなレイアウトに変換
let html = rawText
  .replace(/^## (.+)$/gm, '<h2>$1</h2>')
  .replace(/^# (.+)$/gm, '<h1>$1</h1>')
  .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  .replace(/^- (.+)$/gm, '<li>$1</li>')
  .replace(/(<li>.*<\/li>)/gs, '<ul>$1</ul>')
  .replace(/^---$/gm, '<hr>')
  .replace(/\n/g, '<br>');

const fullHtml = `<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<style>
  body { font-family: Arial, sans-serif; margin: 0; padding: 0; color: #333; font-size: 13px; }
  .page { padding: 40px 50px; }
  .header { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 3px solid #1a1a2e; padding-bottom: 20px; margin-bottom: 30px; }
  .company-info { }
  .company-name { font-size: 22px; font-weight: bold; color: #1a1a2e; }
  .company-contact { font-size: 11px; color: #666; margin-top: 4px; }
  .report-meta { text-align: right; font-size: 11px; color: #666; }
  .report-date { font-size: 13px; font-weight: bold; color: #333; }
  h1 { font-size: 16px; color: #1a1a2e; margin: 20px 0 10px 0; }
  h2 { font-size: 13px; font-weight: bold; background: #f0f0f0; padding: 6px 10px; margin: 20px 0 8px 0; border-left: 4px solid #1a1a2e; }
  ul { margin: 5px 0 10px 20px; padding: 0; }
  li { margin-bottom: 4px; line-height: 1.6; }
  hr { border: none; border-top: 1px solid #ddd; margin: 15px 0; }
  .signoff { margin-top: 40px; display: flex; gap: 60px; }
  .signoff-item { flex: 1; }
  .signoff-label { font-size: 11px; color: #666; margin-bottom: 30px; }
  .signoff-line { border-bottom: 1px dotted #999; margin-bottom: 5px; height: 20px; }
  .footer { border-top: 1px solid #ddd; margin-top: 30px; padding-top: 10px; font-size: 10px; color: #999; text-align: center; }
  strong { color: #1a1a2e; }
</style>
</head>
<body>
<div class="page">
  <div class="header">
    <div class="company-info">
      <div class="company-name">{{COMPANY_NAME}}</div>
      <div class="company-contact">{{COMPANY_PHONE}} | {{COMPANY_EMAIL}}</div>
    </div>
    <div class="report-meta">
      <div class="report-date">Job Service Report</div>
      <div>${today}</div>
    </div>
  </div>
  <div class="content">${html}</div>
  <div class="signoff">
    <div class="signoff-item">
      <div class="signoff-label">Technician Sign-off</div>
      <div class="signoff-line"></div>
      <div style="font-size:11px;color:#666">Name & Date</div>
    </div>
    <div class="signoff-item">
      <div class="signoff-label">Customer Sign-off</div>
      <div class="signoff-line"></div>
      <div style="font-size:11px;color:#666">Name & Date</div>
    </div>
  </div>
  <div class="footer">{{COMPANY_NAME}} | {{COMPANY_PHONE}} | {{COMPANY_EMAIL}} | This report was generated automatically.</div>
</div>
</body>
</html>`;

return [{ json: { html: fullHtml } }];
